import math

def euclidean(a, b):
    return math.sqrt(sum((ai - bi) ** 2 for ai, bi in zip(a, b)))

customers = {
    "alice":   [1200, 2],
    "bob":     [1210, 15],
    "carol":   [4000, 2],
}

def nearest(query_name, customers):
    query = customers[query_name]
    others = {name: point for name, point in customers.items() if name != query_name}
    return min(others, key=lambda name: euclidean(query, others[name]))

print(nearest("alice", customers))   # returns 'bob', even though bob's visit count is wildly different

exercises.solutionCode:
import math

def euclidean(a, b):
    return math.sqrt(sum((ai - bi) ** 2 for ai, bi in zip(a, b)))

customers = {
    "alice":   [1200, 2],
    "bob":     [1210, 15],
    "carol":   [4000, 2],
}

# standardize each feature across the customer population before computing distance
spend_values = [p[0] for p in customers.values()]
visits_values = [p[1] for p in customers.values()]
spend_mean, spend_std = sum(spend_values) / len(spend_values), (sum((v - sum(spend_values)/len(spend_values))**2 for v in spend_values) / len(spend_values)) ** 0.5
visits_mean, visits_std = sum(visits_values) / len(visits_values), (sum((v - sum(visits_values)/len(visits_values))**2 for v in visits_values) / len(visits_values)) ** 0.5

scaled = {
    name: [(spend - spend_mean) / spend_std, (visits - visits_mean) / visits_std]
    for name, (spend, visits) in customers.items()
}

def nearest(query_name, scaled_points):
    query = scaled_points[query_name]
    others = {name: point for name, point in scaled_points.items() if name != query_name}
    return min(others, key=lambda name: euclidean(query, others[name]))

print(nearest("alice", scaled))   # now driven by BOTH features, not spend alone
